//
//  MeetingTitleOwnershipTests.swift
//  WhispererTests
//
//  Verifies that `isAutoGeneratedTitle` classifies defaults correctly and that
//  the `titleIsUserSet` flag on MeetingRecord is honoured — a record flagged as
//  user-set is ineligible for LLM renaming even when its text looks auto-generated.
//

import XCTest
@testable import whisperer

final class MeetingTitleOwnershipTests: XCTestCase {

    // MARK: - isAutoGeneratedTitle

    func testDefaultNoteTitleIsAuto() {
        XCTAssertTrue(MeetingAIService.isAutoGeneratedTitle("Note Sep 5, 2026 10:30 AM"))
        XCTAssertTrue(MeetingAIService.isAutoGeneratedTitle("Meeting Sep 5, 2026 10:30 AM"))
    }

    func testEmptyTitleIsAuto() {
        XCTAssertTrue(MeetingAIService.isAutoGeneratedTitle(""))
        XCTAssertTrue(MeetingAIService.isAutoGeneratedTitle("   "))
    }

    func testProviderNamesAreAuto() {
        for name in ["Zoom", "zoom", "ZOOM", "Microsoft Teams", "Webex",
                     "FaceTime", "Google Meet", "Google Hangouts",
                     "Whereby", "Around", "Slack Huddle", "Slack"] {
            XCTAssertTrue(MeetingAIService.isAutoGeneratedTitle(name),
                          "\"\(name)\" should be classified as auto-generated")
        }
    }

    func testUserTitlesAreNotAuto() {
        // These do NOT match any default-title pattern — heuristic alone already protects them.
        XCTAssertFalse(MeetingAIService.isAutoGeneratedTitle("Product review call"))
        XCTAssertFalse(MeetingAIService.isAutoGeneratedTitle("Design sync"))
        XCTAssertFalse(MeetingAIService.isAutoGeneratedTitle("Quarterly planning"))
    }

    func testHeuristicAloneCanMisclassifyUserTitles() {
        // The text heuristic classifies "Meeting …" and "Note …" as auto-generated even
        // when a human typed them. This is the regression the user reported — "Meeting with
        // the CEO" was overwritten by the LLM.
        //
        // The fix is NOT to change the heuristic (it still serves as a legacy fallback).
        // The fix is that `titleIsUserSet == true` short-circuits `mayRename` BEFORE the
        // heuristic runs. This test documents the known heuristic false-positive.
        XCTAssertTrue(MeetingAIService.isAutoGeneratedTitle("Meeting with the CEO"),
                      "Known false-positive: heuristic alone cannot distinguish this from a default title")
        XCTAssertTrue(MeetingAIService.isAutoGeneratedTitle("Note about Q3 planning"),
                      "Known false-positive: heuristic alone cannot distinguish this from a default title")

        // But once titleIsUserSet is set, the combined check returns false — the flag wins.
        var record = makeMeetingRecord(title: "Meeting with the CEO")
        record.titleIsUserSet = true
        let eligible = !record.titleIsUserSet && MeetingAIService.isAutoGeneratedTitle(record.title)
        XCTAssertFalse(eligible, "titleIsUserSet flag must override the heuristic false-positive")
    }

    // MARK: - MeetingRecord.titleIsUserSet flag

    func testRecordWithUserSetFlagIsIneligibleEvenIfTextLooksAuto() {
        var record = makeMeetingRecord(title: "Meeting Sep 5, 2026 10:30 AM")
        // Without the flag, the heuristic alone would allow renaming.
        XCTAssertTrue(MeetingAIService.isAutoGeneratedTitle(record.title),
                      "Precondition: heuristic alone says this looks auto-generated")

        // Once the user has set the flag, the record must be protected regardless
        // of what the text says.
        record.titleIsUserSet = true
        // The flag-aware eligibility check used by the service is:
        //   !record.titleIsUserSet && isAutoGeneratedTitle(record.title)
        let eligible = !record.titleIsUserSet && MeetingAIService.isAutoGeneratedTitle(record.title)
        XCTAssertFalse(eligible, "A user-set title must not be eligible for LLM renaming")
    }

    func testRecordWithUserSetFlagIsIneligibleForArbitraryText() {
        // The regression the user hit: typed "Zoom" (a provider name) as their title.
        var record = makeMeetingRecord(title: "Zoom")
        record.titleIsUserSet = true
        let eligible = !record.titleIsUserSet && MeetingAIService.isAutoGeneratedTitle(record.title)
        XCTAssertFalse(eligible)
    }

    func testRecordWithoutFlagAndDefaultTitleIsEligible() {
        // Rows written before the flag existed (flag == false) with a default title
        // should still receive an AI title.
        let record = makeMeetingRecord(title: "Note Sep 5, 2026 10:30 AM")
        XCTAssertFalse(record.titleIsUserSet)
        let eligible = !record.titleIsUserSet && MeetingAIService.isAutoGeneratedTitle(record.title)
        XCTAssertTrue(eligible, "Legacy row with auto title should still be eligible")
    }

    func testRecordWithoutFlagButUserLookingTitleIsIneligibleByHeuristic() {
        // No flag, but text is clearly user-written — heuristic protects it too.
        let record = makeMeetingRecord(title: "Design review with Alice")
        XCTAssertFalse(record.titleIsUserSet)
        let eligible = !record.titleIsUserSet && MeetingAIService.isAutoGeneratedTitle(record.title)
        XCTAssertFalse(eligible)
    }

    // MARK: - MeetingRecord Equatable (flag participates)

    func testEqualityConsidersTitleIsUserSetFlag() {
        let a = makeMeetingRecord(title: "Note")
        var b = makeMeetingRecord(title: "Note")
        b.titleIsUserSet = true
        XCTAssertNotEqual(a, b,
            "Records differing only in titleIsUserSet must not compare equal — " +
            "SwiftUI needs to re-render when the flag changes")
    }

    // MARK: - Helpers

    private func makeMeetingRecord(title: String) -> MeetingRecord {
        MeetingRecord(
            title: title,
            language: "en",
            modelUsed: "whisper-base",
            sourceBundleID: nil,
            sourceAppName: nil
        )
    }
}
